const cv = $json.cv || {};
const customerName = $json.customerName || '';

function esc(s) { return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function isArabic(s) { return /[؀-ۿ]/.test(s || ''); }
const arabic = isArabic(cv.tailoredSummary) || isArabic(cv.name);
const labels = arabic
  ? { summary: 'الملخص المهني', experience: 'الخبرة المهنية', education: 'التعليم', certifications: 'الشهادات', skills: 'المهارات', languages: 'اللغات' }
  : { summary: 'Professional Summary', experience: 'Experience', education: 'Education', certifications: 'Certifications', skills: 'Skills', languages: 'Languages' };

function section(title, inner) { return inner ? ('<div class="section"><div class="section-title">' + esc(title) + '</div>' + inner + '</div>') : ''; }

const summaryHtml = cv.tailoredSummary ? ('<p>' + esc(cv.tailoredSummary) + '</p>') : '';

const experienceHtml = (cv.experience || []).map(function(e){ return '
  <div class="exp-entry">
    <div class="exp-head"><span class="exp-title">' + esc(e.title) + '</span><span class="exp-dates">' + esc(e.dates) + '</span></div>
    <div class="exp-company">' + esc(e.company) + '</div>
    <ul>' + (e.bullets || []).map(function(b){ return '<li>' + esc(b) + '</li>'; }).join('') + '</ul>
  </div>'; }).join('');

const educationHtml = (cv.education || []).map(function(ed){ return '<p><strong>' + esc(ed.degree) + '</strong> — ' + esc(ed.institution) + (ed.details ? (' <span class="muted">(' + esc(ed.details) + ')</span>') : '') + '</p>'; }).join('');

const certificationsHtml = (cv.certifications || []).length ? ('<ul>' + cv.certifications.map(function(c){ return '<li>' + esc(c) + '</li>'; }).join('') + '</ul>') : '';

const skillsHtml = (cv.skills || []).length ? ('<p class="pills">' + cv.skills.map(esc).join(' | ') + '</p>') : '';

const languagesHtml = (cv.languages || []).length ? ('<p>' + cv.languages.map(esc).join(' | ') + '</p>') : '';

const bodyHtml = [
  section(labels.summary, summaryHtml),
  section(labels.experience, experienceHtml),
  section(labels.education, educationHtml),
  section(labels.certifications, certificationsHtml),
  section(labels.skills, skillsHtml),
  section(labels.languages, languagesHtml)
].join('
');

const cvHtml = '<!doctype html>
<html lang="' + (arabic ? 'ar' : 'en') + '" dir="' + (arabic ? 'rtl' : 'ltr') + '"><head><meta charset="utf-8">
<title>' + esc(cv.name || customerName) + '</title>
<style>
  * { box-sizing: border-box; }
  body { margin:0; padding:0; background:#ffffff; font-family: Calibri, 'Segoe UI', Arial, sans-serif; color:#111111; }
  .page { max-width:800px; margin:0 auto; background:#ffffff; }
  .header { padding:36px 50px 20px; border-bottom:2px solid #111111; }
  .header h1 { margin:0 0 6px; font-size:26px; font-weight:700; color:#111111; letter-spacing:0.3px; }
  .header .title2 { font-size:14px; font-weight:600; color:#333333; margin:0 0 8px; }
  .header .contact { font-size:12.5px; color:#444444; }
  .body { padding:10px 50px 44px; }
  .section { margin-top:22px; }
  .section-title { font-size:12px; font-weight:700; text-transform:uppercase; letter-spacing:1px; color:#111111; border-bottom:1px solid #999999; padding-bottom:5px; margin-bottom:12px; }
  .section p { margin:6px 0; font-size:13.5px; line-height:1.7; color:#222222; }
  .section ul { margin:6px 0; padding-inline-start:20px; }
  .section li { margin:5px 0; font-size:13px; line-height:1.6; color:#222222; }
  .exp-entry { margin-bottom:16px; }
  .exp-entry:last-child { margin-bottom:0; }
  .exp-head { display:flex; justify-content:space-between; align-items:baseline; gap:12px; }
  .exp-title { font-weight:700; font-size:14.5px; color:#111111; }
  .exp-dates { font-size:12px; color:#555555; white-space:nowrap; }
  .exp-company { font-size:13px; color:#333333; font-style:italic; margin:2px 0 8px; }
  .muted { color:#555555; font-weight:400; font-size:12.5px; }
</style></head>
<body>
  <div class="page">
    <div class="header">
      <h1>' + esc(cv.name || customerName) + '</h1>
      ' + (cv.professionalTitle ? ('<div class="title2">' + esc(cv.professionalTitle) + '</div>') : '') + '
      <div class="contact">' + esc(cv.contactLine) + '</div>
    </div>
    <div class="body">
      ' + bodyHtml + '
    </div>
  </div>
</body></html>';

return { json: Object.assign({}, $json, { cvHtml: cvHtml }) };

const item = $input.item;
const bin = (item.binary && item.binary.data) ? Object.assign({}, item.binary.data) : {};
const customerName = $('Quality Check & Build Email').item.json.customerName;
const jobTitle = $('Quality Check & Build Email').item.json.jobTitle || 'Application';
const safe = function (s) { return String(s).replace(/[\\/:*?"<>|]/g, '-'); };
bin.fileName = 'CV - ' + safe(customerName) + ' - ' + safe(jobTitle) + '.pdf';
bin.mimeType = 'application/pdf';
bin.fileExtension = 'pdf';
return { json: item.json, binary: { data: bin } };

const body = $json.body;
const cv = body.cv || {};
const job = { jobTitle: body.jobTitle, company: body.company, applyUrl: body.applyUrl, source: body.source, applyEmail: body.applyEmail };
const customerName = body.customerName || cv.name || '';
const customerEmail = body.customerEmail || '';
const customerPhone = body.customerPhone ? ('+' + String(body.customerPhone).replace(/^\+/, '')) : '';
const cachedPdfBase64 = body.cachedPdfBase64 || '';

const matchedKeywords = Array.isArray(body.matchedKeywords) ? body.matchedKeywords.filter(Boolean) : [];
const personalizationLine = (body.personalizationLine || '').trim();
const emailSubject = body.emailSubject || (job.jobTitle + ' - ' + customerName);

function isArabicText(s) { return /[؀-ۿ]/.test(s || ''); }
const arabic = isArabicText(cv.tailoredSummary) || isArabicText(cv.name);

const variantSeed = (job.applyUrl || job.company || '').split('').reduce(function (s, c) { return s + c.charCodeAt(0); }, 0);
const variant = (variantSeed % 2 === 0) ? 'A' : 'B';

let emailBody;
if (arabic) {
  emailBody = variant === 'A'
    ? ('السلام عليكم ورحمة الله،\n\nأتقدم لشغل وظيفة ' + job.jobTitle + ' لدى ' + job.company + '، حيث تتوافق خبرتي في ' + personalizationLine + ' مع متطلبات هذه الوظيفة.\n\nأرفق سيرتي الذاتية للاطلاع، وأتطلع لفرصة مناقشة كيف يمكنني إضافة قيمة لفريقكم.\n\nمع خالص التقدير،\n' + customerName + ' — ' + customerPhone)
    : ('تحية طيبة وبعد،\n\nيسعدني تقديم طلبي للانضمام كـ ' + job.jobTitle + ' في ' + job.company + '، حيث أمتلك خبرة عملية مباشرة في ' + personalizationLine + '، وهي من المجالات الأساسية لهذا الدور.\n\nسيرتي الذاتية مرفقة، وأرحب بأي تواصل لمناقشة التفاصيل.\n\nوتفضلوا بقبول فائق الاحترام،\n' + customerName + ' — ' + customerPhone);
} else {
  emailBody = variant === 'A'
    ? ('Dear Hiring Manager,\n\nI am applying for the ' + job.jobTitle + ' position at ' + job.company + ', where my experience in ' + personalizationLine + ' aligns directly with this role\'s requirements.\n\nMy CV is attached for your review, and I would welcome the opportunity to discuss how I can contribute to your team.\n\nBest regards,\n' + customerName + ' — ' + customerPhone)
    : ('Hello,\n\nI would like to express my interest in the ' + job.jobTitle + ' role at ' + job.company + ', where I bring hands-on experience in ' + personalizationLine + ', a core area for this position.\n\nPlease find my CV attached; I look forward to the possibility of speaking further.\n\nKind regards,\n' + customerName + ' — ' + customerPhone);
}

const keywordsUsed = matchedKeywords.join(', ');

function flattenCv(c) {
  const lines = [];
  if (c.name) lines.push(c.name);
  if (c.professionalTitle) lines.push(c.professionalTitle);
  if (c.contactLine) lines.push(c.contactLine);
  lines.push('');
  if (c.tailoredSummary) { lines.push('Professional Summary'); lines.push(c.tailoredSummary); lines.push(''); }
  if ((c.experience||[]).length) {
    lines.push('Experience');
    for (const e of c.experience) {
      lines.push((e.title||'') + ' - ' + (e.company||'') + ' (' + (e.dates||'') + ')');
      for (const b of (e.bullets||[])) lines.push('- ' + b);
    }
    lines.push('');
  }
  if ((c.education||[]).length) {
    lines.push('Education');
    for (const ed of c.education) lines.push((ed.degree||'') + ' - ' + (ed.institution||'') + (ed.details ? ' (' + ed.details + ')' : ''));
    lines.push('');
  }
  if ((c.certifications||[]).length) { lines.push('Certifications'); for (const cert of c.certifications) lines.push('- ' + cert); lines.push(''); }
  if ((c.skills||[]).length) { lines.push('Skills'); lines.push(c.skills.join(', ')); lines.push(''); }
  if ((c.languages||[]).length) { lines.push('Languages'); lines.push(c.languages.join(', ')); }
  return lines.join('\n').trim();
}
const tailoredCv = flattenCv(cv);

let qualityPassed = true;
let qualityReason = '';
if (!cv.tailoredSummary || !(cv.experience||[]).length) { qualityPassed = false; qualityReason = 'CV missing summary or experience entries'; }
else if (!personalizationLine || personalizationLine.length < 8) { qualityPassed = false; qualityReason = 'personalizationLine too short or missing'; }
else if (matchedKeywords.length === 0) { qualityPassed = false; qualityReason = 'no matched keywords returned'; }
else if (/\[.*?\]/.test(personalizationLine) || /\{\{.*?\}\}/.test(personalizationLine)) { qualityPassed = false; qualityReason = 'leftover placeholder text detected'; }

return { json: {
  customerId: body.customerId,
  customerName: customerName,
  customerEmail: customerEmail,
  cv: cv,
  company: job.company,
  jobTitle: job.jobTitle,
  applyUrl: job.applyUrl,
  source: job.source,
  applyEmail: job.applyEmail,
  tailoredCv: tailoredCv,
  emailSubject: emailSubject,
  emailBody: emailBody,
  keywordsUsed: keywordsUsed,
  cachedPdfBase64: cachedPdfBase64,
  qualityPassed: qualityPassed,
  qualityReason: qualityReason
} };
